            jdbc.update(
                    "INSERT INTO note (id, target_type, target_id, body, at) VALUES (?, ?, ?, ?, ?)",
                    noteId, note.get("targetType"),
                    ((Number) note.get("targetId")).longValue(), note.get("text"),
